import numpy as np

N = 32
SHRINK = 1.0 - 1e-12  # tiny strict-inequality guard

def _fallback_6x6_minus_corners():
    xs = (2*np.arange(6) + 1) / 12.0
    ys = (2*np.arange(6) + 1) / 12.0
    centers = []
    for j, y in enumerate(ys):
        for i, x in enumerate(xs):
            if (i, j) in [(0,0), (5,0), (0,5), (5,5)]:
                continue
            centers.append([x, y])
    centers = np.array(centers, dtype=float)[:N]
    radii = np.full(N, (1.0/12.0) * SHRINK, dtype=float)
    return centers, radii

def construct_packing() -> tuple:
    try:
        data = np.load('storage/verity/sumr32_best.npz')
        C = data['centers']; r = data['radii']
        # Return artifact unchanged for centers; micro-shrink radii only
        if C.shape == (N, 2) and r.shape == (N,):
            r2 = np.maximum(r * SHRINK, 1e-16)
            return C.astype(float), r2.astype(float)
    except Exception:
        pass
    # Robust fallback
    return _fallback_6x6_minus_corners()
